    {
        if (readOnly)
            throw ServiceErrors.unsupportedOperation(READ_ONLY_ERROR);

        // check permissions
        ctx.getSecurityHandler().checkResourcePermission(permissions.delete, id);

        // get resource key
        var key = getKey(ctx, id);
        if (key == null)
            throw ServiceErrors.notFound(id);

        // delete from datastore
        try
        {
            if (deleteEntry(ctx, key))
            {
                if (!dataStore.isReadOnly())
                    dataStore.commit();
                ctx.getLogger().info("Deleted resource {}, key={}", id, key);
            }
            else
                throw ServiceErrors.notFound(id);
        }
        catch (DataStoreException e)
        {
            var msg = "Cannot delete '" + id + "': ";
            throw ServiceErrors.requestRejected(msg + e.getMessage());
        }
    }","class":"https://www.commoncoreontologies.org/ont00000653","handle":"c360.semsource-9679ae.workspace.java.method.sensorhub-service-consys-src-main-java-org-sensorhub-impl-service-consys-resource-BaseResourceHandler-java-BaseResourceHandler-delete-8c296d"},{"name":"MVObsSeriesKeyByDataStreamDataType","kind":"class","path":"sensorhub-datastore-h2/src/main/java/org/sensorhub/impl/datastore/h2/MVObsSeriesKeyByDataStreamDataType.java","lines":[33,101],"body":"class MVObsSeriesKeyByDataStreamDataType implements DataType
{
    private static final int MEM_SIZE = 8+12+8; // long ID + instant + long ID


    @Override
    public int compare(Object objA, Object objB)
    {
        MVTimeSeriesKey a = (MVTimeSeriesKey)objA;
        MVTimeSeriesKey b = (MVTimeSeriesKey)objB;

        // first compare datastream IDs
        int comp = Long.compare(a.dataStreamID, b.dataStreamID);
        if (comp != 0)
            return comp;

        // if datastream IDs are the same, compare result time stamps
        comp = a.resultTime.compareTo(b.resultTime);
        if (comp != 0)
            return comp;

        // if result times are equal, compare foi IDs
        return Long.compare(a.foiID, b.foiID);
    }


    @Override
    public int getMemory(Object obj)
    {
        return MEM_SIZE;
    }


    @Override
    public void write(WriteBuffer wbuf, Object obj)
    {
        MVTimeSeriesKey key = (MVTimeSeriesKey)obj;
        wbuf.putVarLong(key.dataStreamID);
        wbuf.putVarLong(key.foiID);
        H2Utils.writeInstant(wbuf, key.resultTime);
    }


    @Override
    public void write(WriteBuffer wbuf, Object[] obj, int len, boolean key)
    {
        for (int i=0; i<len; i++)
            write(wbuf, obj[i]);
    }


    @Override
    public Object read(ByteBuffer buff)
    {
        long dataStreamID = DataUtils.readVarLong(buff);
        long foiID = DataUtils.readVarLong(buff);
        Instant resultTime = H2Utils.readInstant(buff);        
        return new MVTimeSeriesKey(dataStreamID, foiID, resultTime);
    }


    @Override
    public void read(ByteBuffer buff, Object[] obj, int len, boolean key)
    {
        for (int i=0; i<len; i++)
            obj[i] = read(buff);
    }

