        return dsInfo -> {
            // compute hash
            var hash = hashFunc.newHasher()
                .putUnencodedChars(dsInfo.getSystemID().getUniqueID())
                .putUnencodedChars(dsInfo.getOutputName())
                .putInt(dsInfo.getValidTime().hashCode())
                .hash();

